class Solution {
public:
    int numPairsDivisibleBy60(vector<int>& time) {
        long long count[60] = {0};
        for (int t : time) {
            count[t % 60]++;
        }
        long long pairs = 0;
        pairs += count[0] * (count[0] - 1) / 2;
        pairs += count[30] * (count[30] - 1) / 2;
        for (int r = 1; r < 30; r++) {
            pairs += count[r] * count[60 - r];
        }
        return (int)pairs;
    }
};
